parameters.jsCode:
/* PDF -> binary, plus the fields WhatsApp needs.
 *
 * Interakt wants countryCode and phoneNumber as SEPARATE values, and
 * the CRS stores one human-typed string like "+91 82177 56591". Doing
 * the split here means one place to read it and one place to fix it.
 */
const d = $('Reservation confirmed').first().json.body.data;
const b64 = d.voucher.pdfBase64;

if (!b64) {
  throw new Error(
    'No PDF in the payload. Tick "Also attach a ready-made PDF" in ' +
    'Fidato -> Admin -> Integrations and save, then create a booking.'
  );
}

/* Digits only, then peel off the country code.
 * Defaults to +91 when the number was stored without one — every
 * property and guest in this book is Indian. Change if that stops
 * being true; a wrong country code fails silently at Meta. */
const digits = String(d.guestPhone || '').replace(/\D/g, '');
let countryCode = '+91';
let phoneNumber = digits;

if (digits.length > 10) {
  countryCode = '+' + digits.slice(0, digits.length - 10);
  phoneNumber = digits.slice(-10);
}

if (phoneNumber.length !== 10) {
  throw new Error(
    `Guest phone "${d.guestPhone}" is not a 10-digit number after ` +
    'stripping the country code. WhatsApp will reject it.'
  );
}

return [{
  json: {
    filename: d.voucher.filename,
    reference: d.voucher.reference,
    guestName: d.voucher.model.guestName,
    hotelName: d.voucher.model.hotelName,
    checkIn: d.voucher.model.checkIn,
    checkOut: d.voucher.model.checkOut,
    countryCode,
    phoneNumber,
  },
  binary: {
    data: {
      data: b64,
      mimeType: 'application/pdf',
      fileName: d.voucher.filename,
    },
  },
}];

parameters.jsonBody:
